rss.channel:
{{ site.title }} – {{ include.title | xml_escape }}
{{ site.url }}/
{{ include.title | xml_escape }} from {{ site.title }}
en

{% assign cats = include.cats | split: "," %}
{% assign n = 0 %}
{% for post in site.posts %}
  {% if n >= 25 %}{% break %}{% endif %}
  {% unless post.image %}{% continue %}{% endunless %}
  {% unless cats contains post.category %}{% continue %}{% endunless %}
  {% assign n = n | plus: 1 %}
  {% assign img = post.image | absolute_url %}


  {{ post.title | xml_escape }}
  {{ post.url | absolute_url }}
  {{ post.url | absolute_url }}
  {{ post.date | date_to_rfc822 }}
  {{ post.description | default: post.excerpt | strip_html | strip_newlines | xml_escape }}



{% endfor %}
